from collections import Counter, OrderedDict
import re
import logging

logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)


class CFGOperations(object):
    ENB1_X2_ADDR = "$DAEMON_IP"

    def __init__(self):
        self._read_file_pattern = r"[\s]*=[\s]*"

    def _parameters_value_operation(self, original_value, parameters_value):
        """
        Keeps params have same format with original value from file.
        :param original_value: original value in file as string
        :param parameters_value: value used for replacing original value as string
        :return: value as string.
        """
        if original_value == self.ENB1_X2_ADDR:
            parameters_value = r'"' + parameters_value + r'"'
        else:
            number_of_double_quotes = Counter(original_value).get(r'"', None)
            if number_of_double_quotes == 2:
                parameters_value = r'"' + parameters_value + r'"'
        return parameters_value

    @staticmethod
    def _load_parameters_list(parameters_list):
        """
        The func will generate regular expression as key in dict to locate line
        where should be replaced in one file and generate params as value in dict
        used for replacing original params in one file.
        :param parameters_list: parameters as list for modifying cfg file.
        :return: a dictionary contains regular expression and value.
        """
        if parameters_list:
            logger.info("Start to load parameters.")
            parameters_dict = OrderedDict()
            for parameters in parameters_list:
                if len(parameters) == 2:
                    pattern = re.compile(
                        parameters.get("p_name") + r"=([^\s]+)"
                    )
                    value = str(parameters.get("value"))
                    parameters_dict.update({pattern: value})
                else:
                    pattern_expression = "".join(
                        [
                            str(parameters.get("dist_name")),
                            " ",
                            "id=",
                            str(parameters.get("dist_id")),
                        ]
                    )
                    pattern = re.compile(pattern_expression)
                    parameters_dict.update(
                        {
                            pattern: {
                                str(parameters.get("p_name")): str(
                                    parameters.get("value")
                                )
                            }
                        }
                    )
            logger.info("Successfully load parameters for modifying cfg file.")
            return parameters_dict
        else:
            logger.info("Please check parameters you pass into.")

    def _read_file_without_blank(self, input_file):
        """
        Reads content of one file and return content as list.
        :param input_file: file path as string.
        :return: read value as list.
        """
        logger.info("Start to read file.")
        with open(input_file, "r+") as f:
            contents = []
            readlines = f.readlines()
            for line in readlines:
                contents.append(re.sub(self._read_file_pattern, "=", line))
        logger.info("Successfully read file.")
        return contents

    def modify_file(self, input_cfg_file, output_cfg_file, parameters_list):
        """
        Modifies provided CFG file and saves it to provided path.
        :param input_cfg_file: path to CFG file
        :param output_cfg_file: path where modified CFG file will be stored
        :param parameters_list: list of dictionaries with values to modify
        :return:
        """
        contents = self._read_file_without_blank(input_cfg_file)
        parameters_dict = self._load_parameters_list(parameters_list)

        with open(output_cfg_file, "wb") as f:
            logger.info("Start to modify cfg file.")
            for line in contents:
                for pattern, parameters_value in parameters_dict.items():
                    matched_outcomes = pattern.findall(line)
                    if len(matched_outcomes) == 1:
                        matched_outcome = matched_outcomes[0]
                        if isinstance(parameters_value, dict):
                            for p_name, value in parameters_value.items():
                                search_pattern = "".join(
                                    [p_name, "=", r"([^\s]+)"]
                                )
                                original_value = (
                                    re.compile(search_pattern)
                                    .search(line)
                                    .group(1)
                                )
                                replaced_value = (
                                    self._parameters_value_operation(
                                        original_value, value
                                    )
                                )
                                line = line.replace(
                                    original_value, replaced_value
                                )
                        else:
                            replaced_value = self._parameters_value_operation(
                                matched_outcome, parameters_value
                            )
                            line = line.replace(
                                matched_outcome, replaced_value
                            )
                f.write(line.encode("utf-8"))
            logger.info("Successfully modify cfg file.")
